"""Brute-force solvers for ExactCover and SubsetSum, written from the
definitions in problems.py.  These are exponential on purpose: they are only
used as ground truth on tiny instances.
"""

from __future__ import annotations

from itertools import combinations
from typing import Any, Dict, List


def exact_cover_yes(instance: Dict[str, Any]) -> bool:
    """True iff some sub-collection of ``sets`` exactly covers 0..u-1.

    A sub-collection is a choice of a subset of the *positions* in the list
    ``sets`` (so two equal sets are two distinct positions and both may be
    chosen, but then they overlap and the choice is invalid unless the set is
    empty).  Empty sets are irrelevant.
    """
    u: int = instance["universe_size"]
    sets: List[List[int]] = instance["sets"]
    m = len(sets)
    for r in range(m + 1):
        for combo in combinations(range(m), r):
            covered = 0
            ok = True
            for idx in combo:
                for element in sets[idx]:
                    bit = 1 << element
                    if covered & bit:
                        ok = False
                        break
                    covered |= bit
                if not ok:
                    break
            if ok and covered == (1 << u) - 1:
                return True
    return False


def subset_sum_yes(instance: Dict[str, Any]) -> bool:
    """True iff some sub-list of ``numbers`` sums to exactly ``target``."""
    numbers: List[int] = instance["numbers"]
    target: int = instance["target"]
    n = len(numbers)
    for r in range(n + 1):
        for combo in combinations(range(n), r):
            if sum(numbers[i] for i in combo) == target:
                return True
    return False


def solve(problem, instance: Dict[str, Any]) -> bool:
    name = getattr(problem, "name", str(problem))
    if name == "Exact Cover":
        return exact_cover_yes(instance)
    if name == "Subset Sum":
        return subset_sum_yes(instance)
    raise ValueError(f"unknown problem {problem!r}")
EOF
